"use strict";
/* ServiNear UX helpers: accessible names for generated switches, and small interaction polish. */
(() => {
  // Settings switches are generated by app.js templates; give every one an accessible name from its row title.
  function labelSwitches(root) {
    (root || document).querySelectorAll(".settings-switch-row").forEach((row) => {
      const input = row.querySelector('input[type="checkbox"]'), title = row.querySelector("strong");
      if (input && title && !input.getAttribute("aria-label")) input.setAttribute("aria-label", title.textContent.replace(/[^\p{L}\p{N}\s]/gu, "").trim());
    });
  }
  const original = window.renderSettingsView;
  if (typeof original === "function") window.renderSettingsView = function () { const r = original.apply(this, arguments); labelSwitches(arguments[0]); return r; };

  // Change password (Settings > Account)
  document.addEventListener("submit", async (e) => {
    if (e.target.id !== "password-form") return;
    e.preventDefault();
    const f = e.target, msg = document.getElementById("password-msg"), set = (t, ok) => { msg.textContent = t; msg.style.color = ok ? "var(--teal)" : "var(--rust)"; };
    const cur = f.elements.current_password.value, next = f.elements.new_password.value, again = f.elements.confirm_password.value;
    if (next.length < 8) return set("New password must be at least 8 characters.");
    if (next !== again) return set("The two new passwords do not match.");
    const btn = f.querySelector('[type="submit"]'); btn.disabled = true; set("Updating…", true);
    try { const r = await post("/api/auth/change-password", { current_password: cur, new_password: next }); f.reset(); set(r.message, true); toast(r.message); }
    catch (err) { set(err.message); } finally { btn.disabled = false; }
  });

  // Escape closes the notification panel and the mobile menu (dialogs already handle Escape natively).
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    document.querySelectorAll(".notif-dropdown:not(.hidden), .main-nav.open").forEach((el) => { el.classList.add("hidden"); el.classList.remove("open"); });
  });
})();
